const $=s=>document.querySelector(s);
const KEY='daily-three-v2';
let state;try{state=JSON.parse(localStorage.getItem(KEY))||{}}catch{state={}}
state.days ||= {};state.requests ||= {};state.revealed ||= {};
let view=state.profile?'today':'join', questionIndex=0, transition=false, activeMatch=0;
const dateKey=(offset=0)=>{const now=new Date();now.setDate(now.getDate()+offset);return new Intl.DateTimeFormat('en-CA',{timeZone:'America/Los_Angeles',year:'numeric',month:'2-digit',day:'2-digit'}).format(now)};
const today=()=>dateKey();
const bank=[
 {q:'Would you date someone in your major?',a:['Absolutely','Too close to home'],e:['♡','↗'],tag:'A little spicy'},
 {q:'An 8 a.m. class or a Friday evening class?',a:['8 a.m. warrior','Friday night scholar'],e:['☀','☾'],tag:'The student dilemma'},
 {q:'Your friend cancels plans. Your first thought?',a:['Secretly relieved','We’re rescheduling'],e:['☁','✳'],tag:'Be honest'},
 {q:'Group project. Who are you?',a:['Make the shared doc','Wait for the shared doc'],e:['✎','⌛'],tag:'Campus confessions'},
 {q:'A free afternoon in SLO. Where are you?',a:['Up a mountain','Down at the beach'],e:['△','≈'],tag:'Pick your escape'},
 {q:'Someone catches your eye in class. You…',a:['Make the first move','Hope they do'],e:['↗','♡'],tag:'A little spicy'},
 {q:'Your weekend plans are…',a:['Already in the calendar','A future-me problem'],e:['▦','✦'],tag:'How you operate'},
 {q:'The group chat says “hike at sunrise.”',a:['Alarm is set','Absolutely not'],e:['☀','☾'],tag:'Very SLO of you'},
 {q:'You disagree with your friend. You…',a:['Debate it over coffee','Agree to disagree'],e:['☕','☮'],tag:'Pick your energy'},
 {q:'A first date at the dining hall?',a:['Honestly, yes','Please aim higher'],e:['♡','✧'],tag:'A little spicy'},
 {q:'You have one hour before an exam.',a:['One last study sprint','Protect my peace'],e:['✎','☁'],tag:'Student survival'},
 {q:'The aux cord is yours. You play…',a:['A crowd pleaser','My niche obsession'],e:['♫','✳'],tag:'Be honest'}
];
function dayIndex(key){return Math.floor(Date.parse(key+'T12:00:00Z')/86400000)}
function questions(key){const start=((dayIndex(key)%4)+4)%4*3;return bank.slice(start,start+3)}
const samples=[{name:'Elena Park',major:'Architecture',year:'Second year',same:28,total:30,color:'purple',initial:'E'},{name:'Jordan Rivera',major:'Computer Science',year:'Third year',same:26,total:30,color:'green',initial:'J'},{name:'Sam Chen',major:'Environmental Management',year:'Second year',same:25,total:30,color:'peach',initial:'S'}];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('Storage is unavailable. Progress will last for this visit.')}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function go(next){if(['people','match'].includes(next)&&(state.days[today()]||[]).length<3){toast('Finish today’s three questions to see your matches.');return}view=next;render();window.scrollTo({top:0,behavior:'smooth'})}
function header(){return `<header><div class="brand">daily three<span class="campus">CAL POLY · SLO</span></div>${state.profile?`<nav class="nav" aria-label="Main navigation">${[['today','Today'],['profile','Profile']].map(([v,t])=>`<button data-view="${v}" class="${view===v?'active':''}">${t}</button>`).join('')}</nav>`:'<span class="campus">A LITTLE MORE CONNECTED.</span>'}</header>`}
function footer(){return `<footer class="footer"><span>Three daily questions for Cal Poly students.</span><span>Cal Poly student prototype · Not affiliated with the university</span></footer>`}
function join(){return `<main class="join-page"><div class="join-intro"><span class="small-head">CAL POLY, SLO</span><h1>Daily Three.</h1><p>Answer three daily questions.<br>Compare answers with Cal Poly students.</p></div><form id="join-form"><label for="email">Cal Poly email</label><input id="email" name="email" type="email" placeholder="you@calpoly.edu" autocomplete="email" required><div class="row"><div><label for="name">First name</label><input id="name" name="name" placeholder="Your name" maxlength="35" required></div><div><label for="last-name">Last name</label><input id="last-name" name="lastName" placeholder="Last name" maxlength="50" autocomplete="family-name" required></div></div><div><label for="year">Year</label><select id="year" name="year"><option>First year</option><option>Second year</option><option>Third year</option><option>Fourth year</option><option>Fifth year+</option><option>Graduate student</option></select></div><label for="major">Major</label><input id="major" name="major" placeholder="Your major" maxlength="70" required><p class="error" id="join-error" role="alert"></p><button class="primary" type="submit">Join Daily Three</button><p class="fine join-note">By joining, you agree to share your first and last name, major, year, school email, and any socials you add with other students on the app.</p><p class="fine prototype-note">Prototype · Email verification coming soon.</p></form></main>`}
function countDays(){return Object.values(state.days).filter(a=>a.filter(x=>x!==undefined).length===3).length}
function todayScreen(){const answers=state.days[today()]||[];questionIndex=answers.length;if(questionIndex>=3)return results();const q=questions(today())[questionIndex];return `<main class="page"><div class="page-top"><div class="eyebrow"><span class="dot"></span>${new Date().toLocaleDateString('en-US',{timeZone:'America/Los_Angeles',weekday:'long',month:'short',day:'numeric'})}</div><span class="streak">✳ ${countDays()} days played</span></div><div class="play-layout"><section class="question-card"><div class="small-head muted">DAILY THREE</div><div class="progress" aria-label="Question ${questionIndex+1} of 3">${[0,1,2].map(i=>`<span class="${i<=questionIndex?'done':''}"></span>`).join('')}</div><span class="pill">${questionIndex+1} / 3</span><h2>${esc(q.q)}</h2><div class="answers">${q.a.map((a,i)=>`<button class="answer" data-answer="${i}"><strong>${esc(a)}</strong></button>`).join('')}</div><p class="fine" style="margin-top:22px">Select one answer to continue.</p></section><aside class="aside"><div class="orb"><i></i><i></i><i></i></div><h3>A new connection.</h3><p class="muted">Somewhere across campus, someone sees things like you do.</p><p class="muted">Finish today’s three to unlock yesterday’s campus reveal.</p><div class="divider small-head">30 seconds. All you.</div></aside></div></main>`}
function results(){const key=dateKey(-1),qs=questions(key),actual=state.days[key],hasActual=actual?.length===3;const choices=hasActual?actual:[0,1,0];const splits=[68,78,41];return `<main class="page"><div class="section-title"><div><div class="eyebrow"><span class="dot"></span> TODAY’S THREE: COMPLETE ✓</div><h2>Campus results.</h2><p class="muted">Yesterday’s answers, across campus.</p></div><span class="sample">SAMPLE CAMPUS RESULTS</span></div><div class="result-grid">${qs.map((q,i)=>{const pick=choices[i],pct=pick===0?splits[i]:100-splits[i],rare=pct<30;return `<article class="card result ${rare?'rare':''}" style="animation-delay:${i*.12}s"><div class="small-head muted">0${i+1}</div><h3>${esc(q.q)}</h3><div class="number">${pct}<span style="font-size:28px;letter-spacing:-1px">%</span></div><p class="muted" style="font-size:13px">${hasActual?'picked your side.':`picked “${esc(q.a[pick])}.”`}</p><div class="bar"><span style="width:${splits[i]}%"></span></div><div class="bar-legend"><span class="${pick===0?'you':''}">${esc(q.a[0])}<br>${splits[i]}% ${hasActual&&pick===0?'· YOU':''}</span><span class="${pick===1?'you':''}">${esc(q.a[1])}<br>${100-splits[i]}% ${hasActual&&pick===1?'· YOU':''}</span></div>${rare?'<p class="badge">✧ Outside the majority.</p>':''}</article>`}).join('')}</div><p class="notice">${hasActual?'Your highlighted choices are from yesterday. Campus percentages are illustrative.':'You haven’t played yesterday’s questions. These are sample results, not your answers.'} </p><div class="callout"><div><strong>Your closest matches.</strong><p>See your top three matches.</p></div><button class="primary compact" data-view="people">Your closest matches</button></div><div style="display:flex;justify-content:space-between;align-items:center"><span class="fine">Tomorrow brings three new questions.</span><button class="text-btn" data-view="share">Share your answers</button></div></main>`}
function people(){return `<main class="page"><div class="section-title"><h2>Your matches.</h2><span class="sample">Sample profiles</span></div><div class="match-grid">${samples.map((m,i)=>`<button class="card simple-match" data-match="${i}"><div><h3>${esc(m.name)}</h3><p class="muted">${esc(m.major)} · ${m.year}</p></div><div class="number">${Math.round(m.same/m.total*100)}<span>%</span></div><span class="fine">${m.same} of ${m.total} shared answers</span></button>`).join('')}</div></main>`}
function matchScreen(){const m=samples[activeMatch];return `<main class="page"><div class="profile-reveal"><button class="back" data-view="people">← Matches</button><div class="reveal-banner"><div class="eyebrow">SAMPLE PROFILE</div><h2>${esc(m.name)}</h2><p>${esc(m.major)} · ${m.year}</p><div class="number reveal-score">${Math.round(m.same/m.total*100)}<span>%</span></div><p>${m.same} of ${m.total} shared answers</p></div><div class="contacts"><div class="contact">School email <span class="muted">Not provided in sample</span></div></div></div></main>`}
function profile(){const p=state.profile;return `<main class="page"><div class="settings"><div class="eyebrow">PROFILE</div><h2>Your profile.</h2><p class="muted">These details are visible to other students on the app.</p><form id="profile-form" class="card"><label for="pname">First name</label><input id="pname" name="name" required maxlength="35" value="${esc(p.name)}"><label for="plastname">Last name</label><input id="plastname" name="lastName" required maxlength="50" value="${esc(p.lastName||'')}"><div class="row"><div><label for="pmajor">Major</label><input id="pmajor" name="major" required maxlength="70" value="${esc(p.major)}"></div><div><label for="pyear">Year</label><select id="pyear" name="year">${['First year','Second year','Third year','Fourth year','Fifth year+','Graduate student'].map(y=>`<option ${y===p.year?'selected':''}>${y}</option>`).join('')}</select></div></div><label for="pinstagram">Instagram · optional username</label><input id="pinstagram" name="instagram" placeholder="@yourhandle" maxlength="31" pattern="@?[A-Za-z0-9._]+" value="${esc(p.instagram||'')}"><label for="plinkedin">LinkedIn · optional URL</label><input id="plinkedin" name="linkedin" type="url" placeholder="https://www.linkedin.com/in/you" value="${esc(p.linkedin||'')}"><p class="error" id="profile-error" role="alert"></p><p class="fine">Your school email and any socials you add are shared with your profile. Prototype data stays in this browser.</p><button class="primary">Save profile </button></form><button id="signout" class="link-btn">Sign out of this browser</button><p class="fine">Signing out clears your locally saved profile, answers, and profile preferences.</p></div></main>`}
function shareScreen(){const a=state.days[today()]||[],qs=questions(today());return `<main class="page"><div class="settings"><button class="back" data-view="today">← Back to today</button><div class="eyebrow">SHARE</div><h2>Share your answers.</h2><p class="muted">Choose whether to include your answers before sharing.</p><label class="check"><input type="checkbox" id="include-answers" checked><span>Include my answers in the shared text</span></label><div class="share-preview"><div class="small-head">DAILY THREE · CAL POLY</div><h3>My daily answers.</h3><div id="share-answers">${qs.map((q,i)=>`<p>${esc(q.q)}<br><strong>→ ${a[i]===undefined?'Not answered yet':esc(q.a[a[i]])}</strong></p>`).join('')}</div></div><button class="primary" id="share">Share with friends </button><p class="fine">Preview above. Your profile and contact details are never included.</p></div></main>`}
function render(){if(state.profile&&!state.days[today()])state.days[today()]=[];const screens={join,today:todayScreen,people,match:matchScreen,profile,share:shareScreen};$('#app').innerHTML=`<div class="shell">${header()}${(screens[view]||todayScreen)()}${footer()}</div>`;bind()}
function bind(){document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>go(b.dataset.view));document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{if(transition)return;transition=true;b.classList.add('selected');document.querySelectorAll('[data-answer]').forEach(x=>x.disabled=true);state.days[today()].push(Number(b.dataset.answer));save();setTimeout(()=>{transition=false;render();if(state.days[today()].length===3)celebrate()},430)});document.querySelectorAll('[data-match]').forEach(b=>b.onclick=()=>{activeMatch=Number(b.dataset.match);go('match')});
$('#join-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target),email=f.get('email').trim().toLowerCase(),name=f.get('name').trim(),lastName=f.get('lastName').trim(),major=f.get('major').trim();if(!/^[a-z0-9.!#$%&'*+/=?^_`{|}~-]+@calpoly\.edu$/i.test(email)){$('#join-error').textContent='Use your @calpoly.edu email to join.';return}if(!name||!lastName||!major){$('#join-error').textContent='Add your first name, last name, and major to continue.';return}state.profile={email,name,lastName,major,year:f.get('year'),shareEmail:true};save();go('today')});
$('#profile-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target),linkedin=f.get('linkedin').trim();if(linkedin){try{const u=new URL(linkedin);if(u.protocol!=='https:'||!['linkedin.com','www.linkedin.com'].includes(u.hostname))throw 0}catch{$('#profile-error').textContent='Use an https://www.linkedin.com/ profile URL.';return}}if(!f.get('name').trim()||!f.get('lastName').trim()||!f.get('major').trim()){ $('#profile-error').textContent='Name and major cannot be blank.';return}Object.assign(state.profile,{name:f.get('name').trim(),lastName:f.get('lastName').trim(),major:f.get('major').trim(),year:f.get('year'),instagram:f.get('instagram').trim(),linkedin,shareEmail:true});save();toast('Profile saved. Your sharing choices are up to date.')});
$('#signout')?.addEventListener('click',()=>{if(confirm('Clear your profile and answers from this browser?')){state={days:{},requests:{},revealed:{}};save();go('join')}});
$('#include-answers')?.addEventListener('change',e=>{$('#share-answers').hidden=!e.target.checked});$('#share')?.addEventListener('click',async()=>{const include=$('#include-answers').checked,a=state.days[today()]||[],qs=questions(today()),lines=include?qs.map((q,i)=>`${q.q} → ${a[i]===undefined?'Not answered yet':q.a[a[i]]}`).join('\n'):'';const url=location.hostname==='localhost'||location.hostname==='127.0.0.1'?'https://daily-three-cal-poly.mjschoos.chatgpt.site':location.origin;const text=`Daily Three · Cal Poly\nSame campus. Same answers?\n${lines}\n${url}`;try{if(navigator.share){await navigator.share({title:'Daily Three · Cal Poly',text})}else if(navigator.clipboard){await navigator.clipboard.writeText(text);toast('Copied! Drop it in the group chat.')}else{toast('Sharing isn’t supported here. Copy the address from your browser.')}}catch(e){if(e.name!=='AbortError')toast('Couldn’t share. Try copying the page link.')}})}
function celebrate(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const el=document.createElement('div');el.className='confetti';el.setAttribute('aria-hidden','true');el.innerHTML=Array.from({length:35},(_,i)=>`<i style="left:${Math.random()*100}%;background:${['#b9d773','#b899d4','#d9ad78'][i%3]};animation-delay:${Math.random()*.5}s"></i>`).join('');document.body.append(el);setTimeout(()=>el.remove(),2400)}
setInterval(()=>{if(state.profile&&view==='today'&&!state.days[today()]){state.days[today()]=[];render()}},30000);
render();
